+import { describe, it, expect } from "vitest";
+import {
+  DISPATCH_STREAM_KEY,
+  DISPATCH_CONSUMER_GROUP,
+  DISPATCH_DLQ_KEY,
+} from "../src/index.js";
+import type { DispatchJob } from "../src/index.js";
+
+describe("dispatch-stream constants", () => {
+  it("DISPATCH_STREAM_KEY is a non-empty string", () => {
+    expect(typeof DISPATCH_STREAM_KEY).toBe("string");
+    expect(DISPATCH_STREAM_KEY.length).toBeGreaterThan(0);
+  });
+
+  it("DISPATCH_CONSUMER_GROUP is a non-empty string", () => {
+    expect(typeof DISPATCH_CONSUMER_GROUP).toBe("string");
+    expect(DISPATCH_CONSUMER_GROUP.length).toBeGreaterThan(0);
+  });
+
+  it("DISPATCH_DLQ_KEY is a non-empty string", () => {
+    expect(typeof DISPATCH_DLQ_KEY).toBe("string");
+    expect(DISPATCH_DLQ_KEY.length).toBeGreaterThan(0);
+  });
+
+  it("DLQ key is distinct from the main stream key", () => {
+    expect(DISPATCH_DLQ_KEY).not.toBe(DISPATCH_STREAM_KEY);
+  });
+
+  it("constants have stable, well-known values", () => {
+    expect(DISPATCH_STREAM_KEY).toBe("platform:dispatch");
+    expect(DISPATCH_CONSUMER_GROUP).toBe("dispatcher");
+    expect(DISPATCH_DLQ_KEY).toBe("platform:dispatch:dlq");
+  });
+});
+
+describe("DispatchJob type (structural)", () => {
+  it("accepts a minimal valid DispatchJob with all required fields", () => {
+    const job: DispatchJob = {
+      handle: "abc-123",
+      nonce: "nonce-xyz",
+      kind: "impl",
+      task_id: "T1",
+      feature_id: "standalone-executor-hardening",
+      workspace_id: "ws-1",
+      task_repo_url: "git@github.com:org/repo.git",
+      task_repo_branch: "feature/standalone-executor-hardening-T1",
+      task_base_branch: "feature/standalone-executor-hardening",
+      task_repo_base_branch: "main",
+      mgmt_repo_url: "git@github.com:org/mgmt.git",
+      executor_workdir: "/workspace/exec-abc-123",
+      callback_url: "http://broker:3000/callback",
+      enqueued_at: "2026-05-30T17:00:00+0000",
+    };
+    expect(job.handle).toBe("abc-123");
+    expect(job.kind).toBe("impl");
+  });
+
+  it("accepts a DispatchJob with optional fields populated", () => {
+    const job: DispatchJob = {
+      handle: "abc-456",
+      nonce: "nonce-abc",
+      kind: "review-fix",
+      task_id: "T2",
+      feature_id: "some-feature",
