+      task_base_branch: "feature/some-feature",
+      task_repo_base_branch: "main",
+      mgmt_repo_url: "git@github.com:org/mgmt.git",
+      executor_workdir: "/workspace/exec-abc-456",
+      callback_url: "http://broker:3000/callback",
+      budget_tokens: 50000,
+      implementation_model: "claude-sonnet-4-6",
+      enqueued_at: "2026-05-30T18:00:00+0000",
+    };
+    expect(job.budget_tokens).toBe(50000);
+    expect(job.implementation_model).toBe("claude-sonnet-4-6");
+  });
+
+  it("accepts kind=rebase", () => {
+    const job: DispatchJob = {
+      handle: "abc-789",
+      nonce: "nonce-rebase",
+      kind: "rebase",
+      task_id: "T3",
